mapper.select:
/** * selectMnthySchdlRegInfoMngList : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 일정등록정보 관리 화면 조회 */ SELECT AA.BIZ_PLAN_MNG_NO AS BIZ_PLAN_MNG_NO /** 사업계획관리번호 **/ , AA.CRTR_YM AS CRTR_YM /** 기준연월 **/ , AA.BGNG_HR || ' ~ ' || AA.END_HR AS TIMES /** 시작시간 , 종료시간 **/ , AA.TASKWK_TYPE_DEPT_CD AS TASKWK_TYPE_DEPT_CD /** 업무유형기관번호 **/ , AA.MBR_NOCS AS MBR_NOCS /** 회원건수 **/ FROM AYC110 AA WHERE 1=1 AND AA.DEL_YN = 'N'
AND AA.CRTR_YM LIKE #{crtrYm} || '%'
AND AA.TASKWK_TYPE_DEPT_CD = #{deptCd}
ORDER BY AA.CRTR_YM, AA.BGNG_HR

mapper.delete:
/**
*		deleteMnthySchdlRegInfoMng : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 일정등록정보 관리 삭제
*/
	DELETE
	FROM
			AYC110		AA		/** 근무배정표 월별 **/
	WHERE	1=1
		AND	AA.CRTR_YM	=	#{YEAR_MONTH}
		AND	AA.TASKWK_TYPE_DEPT_CD	=	#{DEPT_CD}

/**
*		deleteMnthySchdlRegInfoMng2 : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 일정등록정보 관리 삭제(AYC170)
*/
	DELETE
	FROM
			AYC170		AA		/** 월별게시판댓글할당 **/
	WHERE	1=1
		AND	AA.RLVT_YM	=	#{YEAR_MONTH}
		AND	AA.TASKWK_TYPE_DEPT_CD	=	#{DEPT_CD}

mapper.update:
/**
*		processMnthySchdlRegInfoMng : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 일정등록정보 관리 수정
*/
	MERGE INTO
			AYC110		AA		/** 근무배정표_월별 **/
	USING	DUAL
		ON
		(
			AA.BIZ_PLAN_MNG_NO		=	#{BIZ_PLAN_MNG_NO}
		)
	WHEN MATCHED THEN
		UPDATE SET
			AA.BGNG_HR			=	#{BGNG_HR}
		,	AA.END_HR			=	#{END_HR}
		,	AA.MBR_NOCS			=	#{MBR_NOCS}
		,	AA.LAST_MDFR_ID		=	#{loginId}
		,	AA.LAST_MDFCN_DT	=	SYSDATE
	WHEN NOT MATCHED THEN 
		INSERT
		(
				AA.BIZ_PLAN_MNG_NO
			,	AA.CRTR_YM
			,	AA.TASKWK_TYPE_DEPT_CD
			,	AA.BGNG_HR
			,	AA.END_HR
			,	AA.MBR_NOCS
			,	AA.LAST_MDFR_ID
			,	AA.LAST_MDFCN_DT
			,	AA.FRST_RGTR_ID
			,	AA.FRST_REG_DT

		)
		VALUES
		(
				AYC110_SQ01.NEXTVAL
			,	#{CRTR_YM}
			,	#{deptCd}
			,	#{BGNG_HR}
			,	#{END_HR}
			,	#{MBR_NOCS}
			,	#{loginId}
			,	SYSDATE
			,	#{loginId}
			,	SYSDATE
		)

/**
*		processMnthySchdlRegInfoMng2 : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 일정등록정보 관리 수정(AYC170)
*/
	MERGE INTO
			AYC170		AA		/** 월별게시판댓글할당 **/
	USING	DUAL
		ON
		(
				AA.RLVT_YM				=	#{yearMonth}
			AND	AA.TASKWK_TYPE_DEPT_CD	=	#{deptCd}
			AND	AA.DEL_YN				=	'N'
		)
	WHEN MATCHED THEN
		UPDATE SET
			AA.NTABRD_ASGN_NOCS		=	#{ntabrdAsgnNocs}
		,	AA.CMNT_ASGN_NOCS		=	#{cmntAsgnNocs}
		,	AA.LAST_MDFR_ID			=	#{loginId}
		,	AA.LAST_MDFCN_DT		=	SYSDATE	
	WHEN NOT MATCHED THEN 
		INSERT
		(
				AA.INDEX_SN
			,	AA.RLVT_YM
			,	AA.TASKWK_TYPE_DEPT_CD
			,	AA.NTABRD_ASGN_NOCS	
			,	AA.CMNT_ASGN_NOCS
			,	AA.LAST_MDFR_ID
			,	AA.LAST_MDFCN_DT
			,	AA.FRST_RGTR_ID
			,	AA.FRST_REG_DT
		)
		VALUES
		(
				AYC170_SQ01.NEXTVAL
			,	#{yearMonth}
			,	#{deptCd}
			,	#{ntabrdAsgnNocs}
			,	#{cmntAsgnNocs}
			,	#{loginId}
			,	SYSDATE
			,	#{loginId}
			,	SYSDATE
		)

mapper.insert:
/**
*		insertMnthySchdlRegInfoMng : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 일정등록정보 관리 등록
*/
	INSERT	INTO
			AYC110		AA
	(
			AA.BIZ_PLAN_MNG_NO
		,	AA.CRTR_YM
		,	AA.TASKWK_TYPE_DEPT_CD
		,	AA.BGNG_HR
		,	AA.END_HR
		,	AA.MBR_NOCS
		,   AA.TOT_HR
		,	AA.LAST_MDFR_ID
		,	AA.LAST_MDFCN_DT
		,	AA.FRST_RGTR_ID
		,	AA.FRST_REG_DT
	)
	VALUES
	(
			AYC110_SQ01.NEXTVAL
		,	#{YEAR_MONTH}
		,	#{DEPT_CD}
		,	#{BGNG_TIME}
		,	#{END_TIME}
		,	#{MBR_NOCS}
		,   #{TOT_HR}
		,	#{loginId}
		,	SYSDATE
		,	#{loginId}
		,	SYSDATE
	)

mapper.update:
	/**
    *       updateChcMnthySchdlList : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 선택한 월별 일정등록정보 관리 수정
    */
        UPDATE  AYC110
        SET     BGNG_HR             =       #{BGNG_TIME}
                , END_HR            =       #{END_TIME}
                , MBR_NOCS          =       #{MBR_NOCS}
                , TOT_HR            =       #{TOT_HR}
                , LAST_MDFR_ID      =       #{loginId}
                , LAST_MDFCN_DT     =       SYSDATE
        WHERE   BIZ_PLAN_MNG_NO     =       #{BIZ_PLAN_MNG_NO}

	/**
    *       processMnthyAsgnInfo : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 게시판 댓글 할당량 정보 저장
    */
        MERGE
		INTO    AYC170          /* 월별게시판댓글할당 */
		USING   DUAL
		ON      (
		         INDEX_SN       =       #{INDEX_SN}
		        )
		WHEN MATCHED THEN
		     UPDATE 
		     SET    NTABRD_ASGN_NOCS        =       #{NTABRD_ASGN_NOCS}
		            , CMNT_ASGN_NOCS        =       #{CMNT_ASGN_NOCS}
		            , LAST_MDFR_ID          =       #{loginId}
		            , LAST_MDFCN_DT         =       SYSDATE
		WHEN NOT MATCHED THEN
		     INSERT
		            (
		                    INDEX_SN
		                ,   RLVT_YM
		                ,   TASKWK_TYPE_DEPT_CD
		                ,   NTABRD_ASGN_NOCS
		                ,   CMNT_ASGN_NOCS
		                ,   LAST_MDFR_ID
		                ,   LAST_MDFCN_DT
		                ,   FRST_RGTR_ID
		                ,   FRST_REG_DT
		            )
		     VALUES
		            (
		                    AYC170_SQ01.NEXTVAL
		                ,   #{YEAR_MONTH}
		                ,   #{DEPT_CD}
		                ,   #{NTABRD_ASGN_NOCS}
		                ,   #{CMNT_ASGN_NOCS}
		                ,   #{loginId}
		                ,   SYSDATE
		                ,   #{loginId}
		                ,   SYSDATE
		            )

mapper.select:
	/**
    *       selectChcMnthyDayCnt : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper 
    *        : 선택한 월의 자식테이블(AYC100)에 삭제할 부모테이블(AYC110)의 PK를 FK로 가지고 있는 데이터 COUNT
    */
	   SELECT COUNT(*)
	   FROM   AYC100
	   WHERE  BIZ_PLAN_MNG_NO IN (SELECT BIZ_PLAN_MNG_NO
		                          FROM   AYC110
		                          WHERE  CRTR_YM                    =       #{YEAR_MONTH}
		                          AND    TASKWK_TYPE_DEPT_CD        =       #{DEPT_CD}
		                         )

mapper.delete:
	/**
    *       deleteChcMnthyDayAll : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 존재하면 자식테이블에 존재하는 데이터 삭제
    */
        DELETE  FROM     AYC100
				WHERE    BIZ_PLAN_MNG_NO    IN      (SELECT BIZ_PLAN_MNG_NO
						                             FROM   AYC110
						                             WHERE  CRTR_YM                 =       #{YEAR_MONTH}
						                             AND    TASKWK_TYPE_DEPT_CD     =       #{DEPT_CD}
						                            )

mapper.insert:
/**
*		insertMnthySchdlRegInfoMng2 : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 일정등록정보 관리 등록(AYC170)
*/
	INSERT	INTO
			AYC170		AA		/** 월별게시판댓글할당 **/
	(
			AA.INDEX_SN
		,	AA.RLVT_YM
		,	AA.TASKWK_TYPE_DEPT_CD
		,	AA.NTABRD_ASGN_NOCS
		,	AA.CMNT_ASGN_NOCS
		,	AA.LAST_MDFR_ID
		,	AA.LAST_MDFCN_DT
		,	AA.FRST_RGTR_ID
		,	AA.FRST_REG_DT
	)
	VALUES
	(
			AYC170_SQ01.NEXTVAL
		,	#{YEAR_MONTH}
		,	#{DEPT_CD}
		,	#{NTABRD_ASGN_NOCS}
		,	#{CMNT_ASGN_NOCS}
		,	#{loginId}
		,	SYSDATE
		,	#{loginId}
		,	SYSDATE
	)

mapper.select:
/**
*		insertMnthySchdlRegInfoMngCopy : isry.couns.mngr.workaltmntmng.mapper.MnthySchdlRegInfoMngMapper : 월별 일정등록정보 관리 전월복사
*/
	{call AY_SP_INSERT_PRC_COPY_PRE_MONTH(
			#{exYearMonth, mode=IN, jdbcType=VARCHAR}
		,	#{deptCd, mode=IN, jdbcType=VARCHAR}
		,	#{loginId, mode=IN, jdbcType=VARCHAR}
		,	#{yearMonth, mode=IN, jdbcType=VARCHAR}
		,	#{retVal, mode=OUT, jdbcType=VARCHAR}
	)}
